[void] [System.Reflection.Assembly]::LoadWithPartialName("System.Windows.Forms"); $objNotifyIcon = New-Object System.Windows.Forms.NotifyIcon; $objNotifyIcon.Icon = [System.Drawing.SystemIcons]::Information; $objNotifyIcon.BalloonTipTitle = "ZeroWatch"; $objNotifyIcon.BalloonTipText = "Zerowatch agent is starting an inventory scan"; $objNotifyIcon.Visible = $True; $objNotifyIcon.ShowBalloonTip(5000); Start-Sleep -Seconds 5; $objNotifyIcon.Dispose();
